def vesak():
 return '<circle cx="600" cy="440" r="200" fill="none" stroke="#bc9757" stroke-width="7"/><circle cx="600" cy="440" r="42" fill="#ba9555"/>'+''.join(f'<path d="M600 440V240" stroke="#bc9757" stroke-width="8" transform="rotate({a} 600 440)"/>' for a in range(0,360,45))+'<path d="M600 750C420 740 330 630 340 575Q485 570 600 750C440 650 435 500 470 450Q590 550 600 750C610 550 700 485 730 450Q780 620 600 750C760 580 830 575 870 575Q880 720 600 750" fill="#b46f65" stroke="#e6b7a0" stroke-width="4"/>'
for i,(id,fn) in enumerate([('pagoda',pagoda),('church',church),('caodai',caodai),('mosque',mosque),('altar',altar),('communal',communal),('temple',temple),('hoahao',hoahao),('vesak',vesak),('protestant',protestant)]):
 bg=['#ded8bd','#dfc6b0','#d5c6ab','#bed1c5','#d2b992','#c9c8ac','#c6c5a7','#d7c5a7','#d5bfb0','#d1d3be'][i]
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="900" viewBox="0 0 1200 900"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="{bg}"/><stop offset="1" stop-color="#f3e6ca"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="12" stdDeviation="12" flood-color="#4b4a31" flood-opacity=".12"/></filter><pattern id="grain" width="8" height="8" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".6" fill="#533e2a" opacity=".09"/></pattern></defs><rect width="1200" height="900" fill="url(#sky)"/><circle cx="880" cy="210" r="112" fill="#f8e8bc" opacity=".85"/><path d="M0 580Q180 300 350 540T780 530T1200 490V900H0Z" fill="#778c77" opacity=".18"/><path d="M0 660Q260 420 520 640T1200 570V900H0Z" fill="#768c78" opacity=".19"/><g opacity=".7" fill="#526b57"><ellipse cx="100" cy="580" rx="90" ry="145"/><ellipse cx="1110" cy="560" rx="110" ry="170"/><ellipse cx="50" cy="470" rx="50" ry="75"/></g><path d="M0 760Q500 700 1200 740V900H0Z" fill="#aab08b"/><ellipse cx="600" cy="755" rx="440" ry="48" fill="#6b7257" opacity=".18"/><g filter="url(#shadow)">{fn()}</g><path d="M430 900L500 740H700L820 900" fill="#dfd0af"/><path d="M70 805q70-40 120 0m820-15q80-40 150 0" fill="none" stroke="#718769" stroke-width="15"/><rect width="1200" height="900" fill="url(#grain)"/></svg>'''
 (P/f'{id}.svg').write_text(svg)
(P/'placeholder.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="900"><rect width="1200" height="900" fill="#e9dfca"/><path d="M300 600 600 260 900 600Z" fill="#ad8557"/><text x="600" y="720" text-anchor="middle" font-size="36" fill="#523e30">Minh họa kiến trúc</text></svg>')
Path('public/icons/icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><rect width="512" height="512" rx="100" fill="#9e2a2b"/><circle cx="256" cy="256" r="182" fill="none" stroke="#e8c895" stroke-width="5"/><path d="M148 164h216v40L242 360h-61l120-149H148Z" fill="#f6f1e7"/><path d="M140 387h232" stroke="#b08d57" stroke-width="7"/></svg>')
